/** Independent, strict TLV reader; never uses the production encoder. */
export function fields(payload: string): Record<string, string> {
  const result: Record<string, string> = {};
  let cursor = 0;
  while (cursor < payload.length) {
    const header = payload.slice(cursor, cursor + 4);
    if (!/^\d{4}$/.test(header)) throw new Error(`Invalid TLV header at ${cursor}`);
    const id = header.slice(0, 2);
    const length = Number(header.slice(2));
    cursor += 4;
    if (!length || cursor + length > payload.length || id in result) {
      throw new Error(`Invalid length or duplicate tag ${id}`);
    }
    result[id] = payload.slice(cursor, cursor + length);
    cursor += length;
  }
  return result;
}

// Separate table-driven CRC implementation to catch regressions without asking
// the function under test to verify its own output.
export function independentCrc(text: string): string {
  const table = Array.from({ length: 256 }, (_, i) => {
    let value = i * 256;
    for (let bit = 0; bit < 8; bit++) {
      value = ((value & 0x8000) ? value * 2 ^ 0x1021 : value * 2) & 0xFFFF;
    }
    return value;
  });
  let crc = 0xFFFF;
  for (const ch of text) crc = ((crc << 8) ^ table[((crc >> 8) ^ ch.charCodeAt(0)) & 255]!) & 0xFFFF;
  return crc.toString(16).toUpperCase().padStart(4, '0');
}
